import os, re

# Load grids from session history
def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    # Try to find and load the current session jsonl file
    import glob
    files = glob.glob(os.path.join(d, '..', 'sessions', '*.jsonl')) + \
            glob.glob(os.path.join(d, '../../sessions', '*.jsonl')) + \
            glob.glob(os.path.join(d, '../sessions', '*.jsonl'))
    for f in sorted(files):
        try:
            with open(f) as fp:
                content = fp.read()
            if 'Demo pair' in content or 'Test input' in content:
                return f, content
        except:
            pass
    # Fallback: try the most common paths
    for base_dir in ['.', '..']:
        path = os.path.join(base_dir, 'runs')
        files = glob.glob(os.path.join(path, '**', '*.jsonl'), recursive=True)
        for f in sorted(files):
            try:
                with open(f) as fp:
                    content = fp.read()
                if 'Demo pair' in content:
                    return f, content
            except:
                pass
    return None, ""

f, content = load()
print("Found file:", f if f else "None")
print("Content preview (first 500 chars):", content[:500] if content else "Empty")

