def apply_transformation_v1(grid, bg, val_dirs):
    """Each cell extends diagonally based on its value"""
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    # Track which cells are changed by extensions
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == bg:
                continue
            val = grid[r][c]
            dr_dc = val_dirs.get(val)

            if dr_dc is not None:
                dr, dc = dr_dc
                # Extend until boundary (don't overwrite original positions)
                nr, nc = r + dr, c + dc
                steps = 0
                while 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    result[nr][nc] = val
                    steps += 1
                    nr, nc = nr + dr, nc + dc

    return result

